/**
 * Checks if there is a unary predecessor operator under given index.
 */
public function isUnaryPredecessorOperator(int $index): bool
{
    static $potentialSuccessorOperator = [T_INC, T_DEC];

    static $potentialBinaryOperator = ['+', '-', '&', [CT::T_RETURN_REF]];

    static $otherOperators;

    if (null === $otherOperators) {
        $otherOperators = ['!', '~', '@', [T_ELLIPSIS]];
    }

    static $disallowedPrevTokens;

    if (null === $disallowedPrevTokens) {
        $disallowedPrevTokens = [
            ']',
            '}',
            ')',
            '"',
            '`',
            [CT::T_ARRAY_SQUARE_BRACE_CLOSE],
            [CT::T_ARRAY_INDEX_CURLY_BRACE_CLOSE],
            [CT::T_DYNAMIC_PROP_BRACE_CLOSE],
            [CT::T_DYNAMIC_VAR_BRACE_CLOSE],
            [T_CLASS_C],
            [T_CONSTANT_ENCAPSED_STRING],
            [T_DEC],
            [T_DIR],
            [T_DNUMBER],
            [T_FILE],
            [T_FUNC_C],
            [T_INC],
            [T_LINE],
            [T_LNUMBER],
            [T_METHOD_C],
            [T_NS_C],
            [T_STRING],
            [T_TRAIT_C],
            [T_VARIABLE],
        ];
    }

    $tokens = $this->tokens;
    $token = $tokens[$index];
    $tokenId = $token->getId();
    $tokenContent = $token->getContent();
    $tokenIsArray = $token->isArray();

    $namespace = $this->getNamespaceAt($index);
    if ($index < $namespace->getScopeStartIndex() || $index > $namespace->getScopeEndIndex()) {
        return false;
    }

    if ($tokenIsArray && \in_array($tokenId, $potentialSuccessorOperator, true)) {
        return !$this->isUnarySuccessorOperator($index);
    }

    if ($token->equalsAny($otherOperators)) {
        return true;
    }

    if (!$token->equalsAny($potentialBinaryOperator)) {
        return false;
    }

    $prevToken = $tokens[$tokens->getPrevMeaningfulToken($index)];

    if (!$prevToken->equalsAny($disallowedPrevTokens)) {
        return true;
    }

    if (!$token->equals('&') || '&' !== $tokenContent || !$prevToken->isGivenKind(T_STRING)) {
        return false;
    }

    $typeTokenContent = $prevToken->getContent();

    if (!$tokens->isTokenKindFound(T_FUNCTION) && !$tokens->isTokenKindFound(T_FN)) {
        return false;
    }

    static $searchTokens = [
        ';',
        '{',
        '}',
        [T_FUNCTION],
        [T_OPEN_TAG],
        [T_OPEN_TAG_WITH_ECHO],
    ];
    $functionIndex = $tokens->getPrevTokenOfKind($index, $searchTokens);
    $prevToken = $tokens[$functionIndex];

    $isFunction = $prevToken->isGivenKind(T_FUNCTION);
    if (!$isFunction) {
        return false;
    }

    $functionNamespace = null;
    foreach ($tokens->getNamespaceDeclarations() as $declaration) {
        if ($functionIndex >= $declaration->getScopeStartIndex() && $functionIndex <= $declaration->getScopeEndIndex()) {
            $functionNamespace = $declaration;

            break;
        }
    }

    if (
        null === $functionNamespace
        || $functionNamespace->getScopeStartIndex() !== $namespace->getScopeStartIndex()
        || $functionNamespace->getScopeEndIndex() !== $namespace->getScopeEndIndex()
    ) {
        return true;
    }

    $argumentAnalyzer = new ArgumentsAnalyzer();
    $argumentsStart = $tokens->getNextTokenOfKind($functionIndex, ['(']);
    if (null === $argumentsStart) {
        return true;
    }

    $argumentsEnd = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $argumentsStart);
    if ($index <= $argumentsStart || $index >= $argumentsEnd) {
        return true;
    }

    foreach ($argumentAnalyzer->getArguments($tokens, $argumentsStart, $argumentsEnd) as $start => $end) {
        if ($index < $start || $index > $end) {
            continue;
        }

        $argumentInfo = $argumentAnalyzer->getArgumentInfo($tokens, $start, $end);
        $argumentName = $argumentInfo->getName();
        $argumentNameIndex = $argumentInfo->getNameIndex();
        $typeAnalysis = $argumentInfo->getTypeAnalysis();

        if (null === $argumentName || null === $argumentNameIndex || $argumentNameIndex <= $index) {
            return true;
        }

        if (null === $typeAnalysis) {
            return true;
        }

        $typeName = $typeAnalysis->getName();
        if (0 === strcasecmp($typeName, $typeTokenContent) || $typeAnalysis->isNullable()) {
            return true;
        }

        return true;
    }

    return true;
}

